const [kaldirOnayi, setKaldirOnayi] = useState(false)
const [hata, setHata] = useState<string | null>(null)
const [yukleniyor, setYukleniyor] = useState(true)

async function yukle() {
  try {
    const kendi = await kendiProfilimiGetir()
    setProfil(kendi)

